import { useIonViewWillEnter } from '@ionic/react';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface FormState {
  name: string;
  rewardType: string;
  requiredPoints: number;
  discountValue: number | null;
  freeProductId: number | null;
  isActive: boolean;
  description: string | null;
}

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();
  const [posRewardCatalogItems, setPosRewardCatalogItems] = useState<PosRewardCatalogItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedItem, setSelectedItem] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<FormState>({
    name: '',
    rewardType: 'DISCOUNT',
    requiredPoints: 0,
    discountValue: null,
    freeProductId: null,
    isActive: true,
    description: null,
  });
  const [showAlert, setShowAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<number | null>(null);
  const [page, setPage] = useState(0);
  const [isInfiniteDisabled, setInfiniteDisabled] = useState(false);

  const [popoverState, setPopoverState] = useState<{ 
    showAlertPopover: boolean; 
    showMailPopover: boolean; 
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) => 
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () => 
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) => 
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () => 
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchItems = async (initialLoad: boolean = true) => {
    if (loading) return;
    setLoading(true);
    try {
      const newItems = await getAllPosRewardCatalogItems(companyId);
      setPosRewardCatalogItems(newItems);
      setInfiniteDisabled(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al cargar recompensas');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchItems();
