    if (item) {
      setIsEditing(true);
      setSelectedItem(item);
      setFormState({
        name: item.name,
        rewardType: item.rewardType,
        requiredPoints: item.requiredPoints,
        discountValue: item.discountValue,
        freeProductId: item.freeProductId,
        isActive: item.isActive,
        description: item.description,
      });
    } else {
      setIsEditing(false);
      setSelectedItem(null);
      setFormState({
        name: '',
        rewardType: 'DISCOUNT',
        requiredPoints: 0,
        discountValue: null,
        freeProductId: null,
        isActive: true,
        description: null,
      });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setSaving(false);
    setError('');
  };

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      const payload = {
        ...formState,
        companyId,
        discountValue: formState.rewardType === 'DISCOUNT' ? formState.discountValue : null,
        freeProductId: formState.rewardType === 'FREE_PRODUCT' ? formState.freeProductId : null,
      };

      if (isEditing && selectedItem) {
        await updatePosRewardCatalogItem(selectedItem.catalogItemId, payload);
      } else {
        await createPosRewardCatalogItem(payload);
      }
      await fetchItems();
      handleCloseModal();
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar la recompensa');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (itemToDelete !== null) {
      setLoading(true);
      try {
        await deletePosRewardCatalogItem(itemToDelete, companyId);
        await fetchItems();
      } catch (err) {
        setError((err as Error).message ?? 'Error al eliminar la recompensa');
      } finally {
        setLoading(false);
        setItemToDelete(null);
      }
    }
  };

  const loadMoreItems = (ev: CustomEvent<void>) => {
    // In a real app, you would increment 'page' and fetch more items from the API.
