              <div className="item-content">
                <IonLabel>
                  <h2>{item.name}</h2>
                  <p>Puntos Requeridos: {item.requiredPoints.toFixed(2)}</p>
                  {item.rewardType === 'DISCOUNT' && (
                    <p>Valor de Descuento: ${item.discountValue?.toFixed(2) ?? '0.00'}</p>
                  )}
                  {item.rewardType === 'FREE_PRODUCT' && (
                    <p>ID Producto Gratis: {item.freeProductId ?? 'N/A'}</p>
                  )}
                  <IonBadge color={item.isActive ? 'success' : 'medium'}>
                    {item.rewardType} - {item.isActive ? 'Activa' : 'Inactiva'}
                  </IonBadge>
                  {item.description && <p className="item-description">{item.description}</p>}
                  <p className="item-dates">
                    Creado: {toHermosillo(item.created_At)}
                    {item.updated_at && ` | Actualizado: ${toHermosillo(item.updated_at)}`}
